CREATE TABLE [purchase].[SupplierPaymentTerms] ([PaymentTermId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SupplierPaymentTerms_Id] DEFAULT NEWSEQUENTIALID(), [PaymentTermCode] NVARCHAR(30) NOT NULL, [PaymentTermName] NVARCHAR(100) NOT NULL, [DueDays] INT NOT NULL, [IsDefault] BIT NOT NULL CONSTRAINT [DF_SupplierPaymentTerms_IsDefault] DEFAULT 0, [IsActive] BIT NOT NULL CONSTRAINT [DF_SupplierPaymentTerms_IsActive] DEFAULT 1, [CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_SupplierPaymentTerms_CreatedOn] DEFAULT SYSUTCDATETIME(), [CreatedBy] NVARCHAR(256) NULL, [ModifiedOn] DATETIMEOFFSET NULL, [ModifiedBy] NVARCHAR(256) NULL, [RowVersion] ROWVERSION NOT NULL, CONSTRAINT [PK_SupplierPaymentTerms] PRIMARY KEY ([PaymentTermId]), CONSTRAINT [CK_SupplierPaymentTerms_DueDays] CHECK ([DueDays] >= 0));
GO
CREATE UNIQUE INDEX [UX_SupplierPaymentTerms_Code] ON [purchase].[SupplierPaymentTerms]([PaymentTermCode]);
